      if (beforeRes.rows.length > 0) {
        newPosition = parseFloat(beforeRes.rows[0].position) / 2;
      } else {
        newPosition = calculateEndPosition(db, columnId, oldColumnId, id);
      }
    } else if (afterId) {
      // Insert after a specific card
      const afterRes = await db.query(
        'SELECT position FROM cards WHERE id = $1',
        [afterId]
      );
      if (afterRes.rows.length > 0) {
        newPosition = parseFloat(afterRes.rows[0].position) + 50;
      } else {
        newPosition = calculateEndPosition(db, columnId, oldColumnId, id);
      }
    } else {
      // Append to end
      newPosition = calculateEndPosition(db, columnId, oldColumnId, id);
    }

    // Perform the move atomically
    await db.exec(`
      UPDATE cards 
      SET column_id = $1, position = $2 
      WHERE id = $3
    `, [columnId, newPosition, id]);

    // Check for position collisions and renormalize if needed
    const needsRenormalization = await checkAndRenormalize(db, columnId);

    const card = {
      id: id,
      columnId,
      text: oldCard.text,
      position: newPosition,
      createdAt: oldCard.created_at,
    };

    // Broadcast the move
    broadcast('card-moved', { card, columnId });

    if (needsRenormalization) {
      // Renormalize and broadcast the corrected order
      const normalizedColumns = await getBoardState(db);
      broadcast('columns-renormalized', { columns: normalizedColumns });
    }

    res.json(card);
  } catch (err) {
    console.error('Error moving card:', err);
    res.status(500).json({ error: 'Failed to move card' });
  }
});

function calculateEndPosition(db, columnId, excludeColumnId, excludeCardId) {
  // This is a helper that will be called within a transaction context
  // We need to get the max position in the target column, excluding the card being moved
  const query = `
