    }
  })();

  sseClients.add(res);

  req.on('close', () => {
    sseClients.delete(res);
  });
});

// ---- Start Server ----

async function start() {
  // Initialize database
  await getDb();
  console.log('Database initialized');

  app.listen(PORT, () => {
    console.log(`Kanban board server running on http://localhost:${PORT}`);
  });
}

start().catch((err) => {
  console.error('Failed to start server:', err);
  process.exit(1);
});
