  const res = await db.query(
    'SELECT COALESCE(MAX(position), 0) as max_pos FROM cards WHERE column_id = $1' +
      (excludeCardId ? ' AND id != $2' : ''),
    excludeCardId ? [columnId, excludeCardId] : [columnId]
  );
