// Broadcast an event to all SSE clients
function broadcast(event, data) {
  const message = `event: ${event}\ndata: ${JSON.stringify(data)}\n\n`;
  for (const client of sseClients) {
    if (client.readyState === 1) {
      client.write(message);
    }
  }
}

