    }

    const db = await getDb();

    // Check if column exists
    const columnRes = await db.query('SELECT id FROM columns WHERE id = $1', [columnId]);
    if (columnRes.rows.length === 0) {
      return res.status(404).json({ error: 'Column not found' });
    }

    // Calculate position: end of column
    const cardsRes = await db.query(
      'SELECT MAX(position) as max_pos FROM cards WHERE column_id = $1',
      [columnId]
    );

    const maxPos = parseFloat(cardsRes.rows[0].max_pos || 0);
    const position = maxPos + 50;

