        'SELECT position FROM cards WHERE id = $1',
        [beforeId]
      );
      const afterRes = await db.query(
        'SELECT position FROM cards WHERE id = $1',
        [afterId]
      );

      if (beforeRes.rows.length > 0 && afterRes.rows.length > 0) {
        newPosition = (parseFloat(beforeRes.rows[0].position) + parseFloat(afterRes.rows[0].position)) / 2;
      } else {
        newPosition = calculateEndPosition(db, columnId, oldColumnId, id);
