    res.status(500).json({ error: 'Failed to move card' });
  }
});

function calculateEndPosition(db, columnId, excludeColumnId, excludeCardId) {
  // This is a helper that will be called within a transaction context
  // We need to get the max position in the target column, excluding the card being moved
  const query = `
