import { PGlite } from '@electric-sql/pglite';
import http from 'http';

// Connect to SSE stream
const req = http.get('http://localhost:3001/api/stream', (res) => {
  let data = '';
  res.on('data', (chunk) => {
    data += chunk.toString();
    console.log('Received:', chunk.toString().trim());
  });
  res.on('end', () => {
    console.log('--- Stream ended ---');
    process.exit(0);
  });
});

req.on('error', (e) => {
  console.error('Request error:', e.message);
  process.exit(1);
});

// Wait a bit then create a card
setTimeout(async () => {
  const db = await PGlite.create({ dataDir: './pglite-data' });
  const board = await db.query('SELECT id FROM columns WHERE title = \$1', ['In Progress']);
  const colId = board.rows[0].id;

  console.log('Creating card...');
  await db.query('INSERT INTO cards (id, column_id, text, position, created_at) VALUES (\$1, \$2, \$3, \$4, \$5)',
    ['test-card-123', colId, 'SSE Test via Node', 150, new Date().toISOString()]);

  console.log('Card created, waiting for SSE...');
}, 2000);

// Give it time to receive events
setTimeout(() => {
  req.destroy();
  process.exit(0);
}, 5000);
""}

