{
  "name": "kanban-board",
  "version": "1.0.0",
  "type": "module",
  "private": true,
  "scripts": {
    "dev": "concurrently \"npm run dev:server\" \"npm run dev:client\"",
    "dev:server": "node server/server.js",
    "dev:client": "cd client && npx vite"
  },
  "dependencies": {
    "@electric-sql/pglite": "^0.2.0",
    "cors": "^2.8.5",
    "express": "^4.18.2"
  },
  "devDependencies": {
    "concurrently": "^8.2.2"
  }
}

import { PGlite } from '@electric-sql/pglite';
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';
import { mkdirSync } from 'fs';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

const DATA_DIR = join(__dirname, '..', 'pglite-data');

// Ensure data directory exists
mkdirSync(DATA_DIR, { recursive: true });

let db = null;

export async function getDb() {
  if (db) return db;

  db = await PGlite.create({
    dataDir: DATA_DIR,
    relaxedDurability: true,
  });

  await initializeSchema();
  return db;
}

async function initializeSchema() {
  // Create tables
  await db.exec(`
    CREATE TABLE IF NOT EXISTS columns (
      id TEXT PRIMARY KEY,
      title TEXT NOT NULL,
      position REAL NOT NULL
    );

    CREATE TABLE IF NOT EXISTS cards (
      id TEXT PRIMARY KEY,
      column_id TEXT NOT NULL REFERENCES columns(id) ON DELETE CASCADE,
      text TEXT NOT NULL,
      position REAL NOT NULL,
      created_at TEXT NOT NULL
    );

    CREATE INDEX IF NOT EXISTS idx_cards_column_position ON cards(column_id, position);
  `);

  // Seed default columns if none exist
  const count = await db.query('SELECT COUNT(*) as count FROM columns');
  if (count.rows[0].count === 0) {
    const columns = [
      { id: generateId(), title: 'To Do', position: 0 },
      { id: generateId(), title: 'In Progress', position: 100 },
      { id: generateId(), title: 'Done', position: 200 },
    ];

    const now = new Date().toISOString();

    for (const col of columns) {
      await db.query(
        'INSERT INTO columns (id, title, position) VALUES ($1, $2, $3)',
        [col.id, col.title, col.position]
      );
    }

    // Insert a sample card in To Do to demonstrate the board
    const sampleCol = columns[0];
    await db.query(
      'INSERT INTO cards (id, column_id, text, position, created_at) VALUES ($1, $2, $3, $4, $5)',
      [generateId(), sampleCol.id, 'Sample card - drag me around!', 50, now]
    );
  }
}

function generateId() {
  return Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 15);
}

export { generateId };

import express from 'express';
import cors from 'cors';
import { getDb, generateId } from './db.js';

const app = express();
const PORT = process.env.PORT || 3001;

// Middleware
app.use(cors());
app.use(express.json());

// SSE connections management
const sseClients = new Set();

// Broadcast an event to all SSE clients
function broadcast(event, data) {
  const message = `event: ${event}\ndata: ${JSON.stringify(data)}\n\n`;
  for (const client of sseClients) {
    if (!client.writableEnded) {
      try {
        client.write(message);
      } catch (e) {
        // Client may have disconnected
      }
    }
  }
}

// ---- Helper: Get board state as JSON ----

async function getBoardState(db) {
  const columnsRes = await db.query(
    'SELECT id, title, position FROM columns ORDER BY position'
  );

  const columns = columnsRes.rows.map((col) => ({
    id: col.id,
    title: col.title,
    position: parseFloat(col.position),
    cards: [],
  }));

  const cardsRes = await db.query(
    'SELECT id, column_id, text, position, created_at FROM cards ORDER BY column_id, position'
  );

  for (const card of cardsRes.rows) {
    const column = columns.find((c) => c.id === card.column_id);
    if (column) {
      column.cards.push({
        id: card.id,
        columnId: card.column_id,
        text: card.text,
        position: parseFloat(card.position),
        createdAt: card.created_at,
      });
    }
  }

  return columns;
}

// ---- Helper: Calculate end position for a column ----

async function getEndPosition(db, columnId, excludeCardId = null) {
  const res = await db.query(
    'SELECT COALESCE(MAX(position), 0) as max_pos FROM cards WHERE column_id = $1' +
      (excludeCardId ? ' AND id != $2' : ''),
    excludeCardId ? [columnId, excludeCardId] : [columnId]
  );
  return parseFloat(res.rows[0].max_pos) + 50;
}

// ---- Helper: Renormalize a column's positions ----

async function renormalizeColumn(db, columnId) {
  const cardsRes = await db.query(
    'SELECT id, position FROM cards WHERE column_id = $1 ORDER BY position',
    [columnId]
  );

  const cards = cardsRes.rows;
  if (cards.length === 0) return;

  const spacing = 100;
  const start = 50;

  for (let i = 0; i < cards.length; i++) {
    const newPos = start + i * spacing;
    await db.query(
      'UPDATE cards SET position = $1 WHERE id = $2 AND column_id = $3',
      [newPos, cards[i].id, columnId]
    );
  }
}

