}

h1 {
  color: white;
  margin-bottom: 20px;
  font-size: 24px;
}

.board {
  display: flex;
  gap: 16px;
  overflow-x: auto;
  padding-bottom: 20px;
  align-items: flex-start;
}

.column {
  background: #ebecf0;
  border-radius: 8px;
